package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Any missing required key, malformed value or unknown key makes {@link #load} throw a {@link ConfigException}
 * that lists every problem found, so the service never starts on a configuration it did not understand.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    static final String UPSTREAM_URL = "upstream.url";
    static final String API_TOKEN = "api.token";
    static final String WORKER_THREADS = "worker.threads";
    static final String QUEUE_CAPACITY = "queue.capacity";
    static final String RETRY_MAX_ATTEMPTS = "retry.max-attempts";
    static final String REQUEST_TIMEOUT = "request.timeout";
    static final String METRICS_ENABLED = "metrics.enabled";

    private static final Set<String> KNOWN_KEYS = Set.of(
            UPSTREAM_URL, API_TOKEN, WORKER_THREADS, QUEUE_CAPACITY, RETRY_MAX_ATTEMPTS, REQUEST_TIMEOUT,
            METRICS_ENABLED);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private final Path file;
    private final Properties properties;
    private final List<String> problems = new ArrayList<>();

    private ConfigLoader(Path file, Properties properties) {
        this.file = file;
        this.properties = properties;
    }

    public static ServiceConfig load(Path file) {
        return new ConfigLoader(file, read(file)).parse();
    }

    private ServiceConfig parse() {
        rejectUnknownKeys();
        ServiceConfig config = new ServiceConfig(
                upstreamUrl(),
                requiredText(API_TOKEN),
                intValue(WORKER_THREADS, DEFAULT_WORKER_THREADS, 1),
                intValue(QUEUE_CAPACITY, DEFAULT_QUEUE_CAPACITY, 1),
                intValue(RETRY_MAX_ATTEMPTS, DEFAULT_RETRY_ATTEMPTS, 0),
                duration(REQUEST_TIMEOUT, DEFAULT_REQUEST_TIMEOUT),
                booleanValue(METRICS_ENABLED, false));
        if (!problems.isEmpty()) {
            throw new ConfigException(describeProblems());
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("Cannot read configuration file " + file.toAbsolutePath() + ": " + e);
        }
        return properties;
    }

    private void rejectUnknownKeys() {
        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add(key + " is not a known setting (check the spelling)");
            }
        }
    }

    private URI upstreamUrl() {
        String raw = requiredText(UPSTREAM_URL);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            if (isHttpUrlWithHost(uri)) {
                return uri;
            }
        } catch (URISyntaxException e) {
            // reported below
        }
        problems.add(UPSTREAM_URL + " must be an http:// or https:// URL with a host, but was '" + raw + "'");
        return null;
    }

    private static boolean isHttpUrlWithHost(URI uri) {
        String scheme = uri.getScheme();
        boolean http = "http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme);
        return http && uri.getHost() != null;
    }

    private String requiredText(String key) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private int intValue(String key, int defaultValue, int minimum) {
        String raw = optionalText(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw);
            if (value >= minimum) {
                return value;
            }
        } catch (NumberFormatException e) {
            // reported below
        }
        problems.add(key + " must be a whole number of at least " + minimum + ", but was '" + raw + "'");
        return defaultValue;
    }

    private Duration duration(String key, Duration defaultValue) {
        String raw = optionalText(key);
        if (raw == null) {
            return defaultValue;
        }
        Matcher matcher = DURATION.matcher(raw);
        if (matcher.matches()) {
            try {
                return toDuration(Long.parseLong(matcher.group(1)), matcher.group(2));
            } catch (ArithmeticException | NumberFormatException e) {
                // reported below
            }
        }
        problems.add(key + " must be a whole number followed by ms, s or m (for example 30s), but was '" + raw + "'");
        return defaultValue;
    }

    private static Duration toDuration(long amount, String unit) {
        return switch (unit) {
            case "ms" -> Duration.ofMillis(amount);
            case "s" -> Duration.ofSeconds(amount);
            default -> Duration.ofMinutes(amount);
        };
    }

    private boolean booleanValue(String key, boolean defaultValue) {
        String raw = optionalText(key);
        if (raw == null) {
            return defaultValue;
        }
        if (raw.equalsIgnoreCase("true")) {
            return true;
        }
        if (raw.equalsIgnoreCase("false")) {
            return false;
        }
        problems.add(key + " must be true or false, but was '" + raw + "'");
        return defaultValue;
    }

    /** The trimmed value of an optional key, or null when the key is absent. A present but empty value is kept. */
    private String optionalText(String key) {
        String raw = properties.getProperty(key);
        return raw == null ? null : raw.trim();
    }

    private String describeProblems() {
        StringBuilder message = new StringBuilder("Invalid configuration in ")
                .append(file.toAbsolutePath())
                .append(':');
        for (String problem : problems) {
            message.append(System.lineSeparator()).append("  - ").append(problem);
        }
        return message.toString();
    }
}

